style.css:
@-moz-document domain("www.roblox.com") {
/* page-level */
  html, body {
    background: #000 !important;
  }

  /* common containers / sections */
  body, html,
  #container, .container, .content, main, header, nav, footer,
  .site, .page, .section, .rbx-body, .rbx-navbar, .rbx-topnav,
  .site-footer, .site-header, .page-content {
    background-color: #000 !important;
    background-image: none !important;
  }

  /* panels, cards, modals, dropdowns */
  .panel, .panel-default, .card, .card-body, .card-header,
  .modal, .modal-content, .modal-dialog, .modal-backdrop,
  .dropdown-menu, .popover, .tooltip,
  .alert, .secondary, .hero, .banner {
    background-color: #000 !important;
    background-image: none !important;
    box-shadow: none !important;
  }

  /* site specific UI blocks that often have own backgrounds */
  .scroller, .page-container, .content-container, .rbx-items, .catalog,
  .item-card, .thumbnail, .game-card, .game-details, .ab-slot {
    background-color: #000 !important;
  }

  /* inputs / buttons: darken but keep text color as-is */
  input, textarea, select, button, .btn, .form-control, .search-input {
    background-color: #0b0b0b !important;
    border-color: #222 !important;
    color: inherit !important;
  }

  /* navigation bars, headers */
  header, .top-nav, .navbar, .site-nav, .rbx-header {
    background-color: #000 !important;
  }

  /* toolbars / footers */
  footer, .footer, .site-footer, .rbx-footer {
    background-color: #000 !important;
  }

  /* cards and hover states (slightly lighter so they stand out) */
  .card:hover, .panel:hover, .game-card:hover, .item-card:hover {
    background-color: #0d0d0d !important;
  }

  /* keep images, icons, videos unchanged */
  img, svg, video {
    background: transparent !important;
    filter: none !important;
  }

  /* avoid hiding borders that might be necessary for contrast */
  * {
    outline-color: initial !important;
  }

  /* some sites use inline gradients — remove them so backgrounds stay solid black */
  [style*="background: linear-gradient"], [style*="background-image: linear-gradient"] {
    background-image: none !important;
    background: #000 !important;
  }

  /* safety: don't force text color changes — user requested "minus text" so we leave colors alone */
}
